using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class VerifyColliderBounds {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B4_DeskAndCollision/"));
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");string original=SceneManager.GetActiveScene().path;var candidates=JArray.Parse(File.ReadAllText(H+"ghost_candidates.json")).Where(j=>(int)j["empty"]>3).ToDictionary(j=>(string)j["asset"]);var log=new List<object>();try{foreach(string f in new[]{"B5","B4"}){var s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+f+"_Circular.unity");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).ToArray();foreach(var t in ts){var mf=t.GetComponent<MeshFilter>();var boxes=t.GetComponents<BoxCollider>();if(!mf||!mf.sharedMesh||boxes.Length<2)continue;string asset=AssetDatabase.GetAssetPath(mf.sharedMesh);if(!candidates.TryGetValue(asset,out var row))continue;var bs=boxes.Select(b=>{var q=new Bounds(b.center,b.size);q.Expand(.0002f);return q;}).ToArray();int outside=mf.sharedMesh.vertices.Count(p=>!bs.Any(b=>b.Contains(p)));int blocked=0;foreach(var p in row["points"]){float x=(float)p[0],z=(float)p[2];bool hit=bs.Any(b=>{float dx=Mathf.Max(b.min.x-x,0,x-b.max.x),dz=Mathf.Max(b.min.z-z,0,z-b.max.z),dy=Mathf.Max(b.min.y-1.48f,0,.38f-b.max.y);return dx*dx+dy*dy+dz*dz<.28f*.28f;});if(hit)blocked++;}log.Add(new{floor=f,name=t.name,asset,bands=boxes.Length,uncoveredVertices=outside,previousEmptySamples=(int)row["empty"],stillBlockedSamples=blocked});}}}finally{EditorSceneManager.OpenScene(original);}File.WriteAllText(H+"bounds_verification.json",JsonConvert.SerializeObject(log,Formatting.Indented));return new{checkedObjects=log.Count,uncovered=log.Sum(x=>(int)x.GetType().GetProperty("uncoveredVertices").GetValue(x)),before=log.Sum(x=>(int)x.GetType().GetProperty("previousEmptySamples").GetValue(x)),after=log.Sum(x=>(int)x.GetType().GetProperty("stillBlockedSamples").GetValue(x))};}
}
